package net.civeira.phylax.feature.observe.observedsource.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSource;
import net.civeira.phylax.feature.observe.observedsource.domain.valueobject.DroppedCountVO;

class DroppedCountValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of dropped count of observed source")
  void test_dropped_count_value_holder_assign_plain_value() {
    Object holder = new Object();
    DroppedCountValueHolder<Object> value = new DroppedCountValueHolder<>(holder);
    Assertions.assertSame(holder, value.droppedCount(1), "Setters must return the holder");
    Assertions.assertTrue(value.getDroppedCountValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getDroppedCount().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.droppedCountNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getDroppedCountValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getDroppedCount().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of dropped count of observed source")
  void test_dropped_count_value_holder_assign_value_object() {
    Object holder = new Object();
    DroppedCountValueHolder<Object> value = new DroppedCountValueHolder<>(holder);
    DroppedCountVO vo = DroppedCountVO.from(1);
    Assertions.assertFalse(value.getDroppedCountValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.droppedCount(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getDroppedCountValue().orElseThrow());
    Assertions.assertSame(holder, value.droppedCount(Optional.empty()));
    Assertions.assertFalse(value.getDroppedCountValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.droppedCount(Optional.of(vo)));
    Assertions.assertSame(vo, value.getDroppedCountValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of dropped count of observed source against the original")
  void test_dropped_count_value_holder_read() {
    Object holder = new Object();
    DroppedCountValueHolder<Object> value = new DroppedCountValueHolder<>(holder);
    DroppedCountVO vo = DroppedCountVO.from(1);
    DroppedCountVO other = DroppedCountVO.from(1);
    ObservedSource original = Mockito.mock(ObservedSource.class);
    Mockito.when(original.getDroppedCountValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readDroppedCount(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readDroppedCount(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.droppedCount(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readDroppedCount(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readDroppedCount(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of dropped count of observed source")
  void test_dropped_count_value_holder_unset() {
    Object holder = new Object();
    DroppedCountValueHolder<Object> value = new DroppedCountValueHolder<>(holder);
    DroppedCountVO vo = DroppedCountVO.from(1);
    value.droppedCount(vo);
    Assertions.assertSame(holder, value.unsetDroppedCountIfMatches("droppedCount_other"));
    Assertions.assertTrue(value.getDroppedCountValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetDroppedCountIfMatches("droppedCount"));
    Assertions.assertFalse(value.getDroppedCountValue().isPresent(),
        "The field name must clear the value");
    value.droppedCount(vo);
    Assertions.assertSame(holder, value.unsetDroppedCount());
    Assertions.assertFalse(value.getDroppedCountValue().isPresent(), "Unset must clear the value");
  }
}
